import { useId } from 'react'

import { cx } from '~/lib/cx'
import styles from './radio-group.module.scss'

export type RadioOption = {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export type RadioOrientation = 'vertical' | 'horizontal'

export interface RadioGroupProps {
  options: RadioOption[]
  value?: string
  onChange?: (value: string) => void
  name?: string
  label?: string
  className?: string
  orientation?: RadioOrientation
}

export function RadioGroup({
  options,
  value,
  onChange,
  name,
  label,
  className,
  orientation = 'vertical',
}: RadioGroupProps) {
  const autoName = useId()
  const groupName = name ?? autoName

  return (
    <fieldset className={cx(styles.root, className)}>
      {label ? <legend className={styles.legend}>{label}</legend> : null}

      <div
        className={cx(
          styles.options,
          orientation === 'horizontal' ? styles.horizontal : styles.vertical,
        )}
      >
        {options.map((option) => {
          const id = `${groupName}-${option.value}`
          const selected = value === option.value

          return (
            <label
              key={option.value}
              htmlFor={id}
              className={cx(styles.option, option.disabled && styles.disabled)}
              data-state={selected ? 'checked' : undefined}
              data-disabled={option.disabled ? 'true' : undefined}
            >
              <span className={styles.controlWrap}>
                <input
                  id={id}
                  type="radio"
                  name={groupName}
                  value={option.value}
                  checked={selected}
                  disabled={option.disabled}
                  onChange={() => onChange?.(option.value)}
                  className={styles.control}
                />
                <span className={styles.dot} aria-hidden />
              </span>

              <span className={styles.text}>
                <span className={styles.label}>{option.label}</span>
                {option.description ? (
                  <span className={styles.description}>
                    {option.description}
                  </span>
                ) : null}
              </span>
            </label>
          )
        })}
      </div>
    </fieldset>
  )
}

@use 'styles' as vz;

.root {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.legend {
  padding: 0;
  margin-bottom: vz.space(2);
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
}

.options {
  display: flex;
  gap: vz.space(3);
}

.vertical {
  flex-direction: column;
}

.horizontal {
  flex-flow: row wrap;
}

.option {
  display: flex;
  align-items: flex-start;
  gap: vz.space(2.5);
  padding: vz.space(2.5) vz.space(3);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    border-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent', 0.6);
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.option[data-state='checked'] {
  border-color: vz.color('ring', 0.55);
  background: vz.color('accent');
}

.disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.control-wrap {
  position: relative;
  display: inline-flex;
  flex: none;
  width: 1.125rem;
  height: 1.125rem;
  margin-top: 0.0625rem;
}

.control {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  opacity: 0;
  cursor: inherit;
}

.dot {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border: 1px solid vz.color('input');
  border-radius: vz.radius('full');
  background: vz.color('card');
  transition: border-color vz.duration('fast') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.dot::after {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: vz.radius('full');
  background: vz.color('primary');
  content: '';
  opacity: 0;
  transform: scale(0.4);
  transition:
    opacity vz.duration('fast') vz.ease('out'),
    transform vz.duration('fast') vz.ease('spring');

  @include vz.motion-reduce {
    transition: none;
  }
}

.control:checked + .dot {
  border-color: vz.color('primary');
}

.control:checked + .dot::after {
  opacity: 1;
  transform: scale(1);
}

.control:focus-visible + .dot {
  outline: 2px solid vz.color('ring', 0.6);
  outline-offset: 2px;
}

.text {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  min-width: 0;
}

.label {
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
  line-height: 1.35;
}

.description {
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.45;
}
